"""score.py on the hand-made fixture (tests/fixtures, regenerated by make_fixture.py): every figure below is counted by hand.

Fixture reports (cr-0001 ... cr-0007), run A / run B:
  1 Bukhari, labelled correct          A exact          B exact
  2 Muslim, defective, lost name اسماء A adds the name  B does not
  3 al-Kafi, correct, diacritics       A exact (fenced) B exact
  4 Muslim, correct                    A drops a link   B exact
  5 Muslim, defective, lost سالما      A reproduces the stored chain (misses the name)   B same
  6 Rabi', correct                     A has no output  B exact
  7 Muslim, two correct routes         A right reading, offsets shifted by 2, «بهذا الإسناد» as a link   B exact
"""
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from score import fold_exact, loosely_equal, score, wilson  # noqa: E402
from validate import load_reports  # noqa: E402

FIXTURES = ROOT / "tests" / "fixtures"


def counts(result: dict, group: str, name: str) -> tuple[int, int]:
    successes, total = result[group][name]
    return successes, total


class ScoreFixtureTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.directory = tempfile.TemporaryDirectory()
        cls.out = Path(cls.directory.name)
        cls.result = score(load_reports(FIXTURES / "reports.jsonl"), FIXTURES / "run_a", FIXTURES / "run_b", cls.out)
        cls.table = (cls.out / "disagreements.tsv").read_text(encoding="utf-8").splitlines()

    @classmethod
    def tearDownClass(cls):
        cls.directory.cleanup()

    def test_validation_shares(self):
        self.assertEqual(counts(self.result, "ALL", "strict_valid"), (5, 7))       # 6 has no file, 7 has shifted offsets
        self.assertEqual(counts(self.result, "ALL", "repaired_valid"), (6, 7))     # repair rescues only the miscounted offsets
        self.assertEqual(counts(self.result, "ALL", "fenced"), (1, 7))

    def test_labelled_correct_chains(self):
        # 1, 3 (diacritics and a markdown fence), 7a and 7b match; 4 lost a link; 6 is not analysable
        self.assertEqual(counts(self.result, "ALL", "correct_exact"), (4, 5))
        self.assertEqual(counts(self.result, "sunni:muslim", "correct_exact"), (2, 3))

    def test_labelled_defective_chains(self):
        self.assertEqual(counts(self.result, "ALL", "defective_differs"), (1, 2))   # 2 differs (the name added), 5 is reproduced
        self.assertEqual(counts(self.result, "ALL", "expected_found"), (1, 2))      # A contains اسماء, lacks سالما

    def test_run_agreement(self):
        self.assertEqual(counts(self.result, "ALL", "run_agreement"), (4, 6))       # 2 and 4 differ; 6 has no run A output

    def test_disagreements_list_exactly_what_a_human_should_read(self):
        expected = [
            ("run A and run B routes differ", "cr-0002"),
            ("labelled correct, reader differs", "cr-0004"),
            ("run A and run B routes differ", "cr-0004"),
            ("labelled defective, reader reproduces stored", "cr-0005"),
            ("reader lacks the name the note says was lost", "cr-0005"),
            ("no valid output (missing)", "cr-0006"),
        ]
        rows = [(line.split("	")[1], line.split("	")[2]) for line in self.table[1:]]
        self.assertEqual(len(rows), len(expected))
        for prefix, report_id in expected:
            self.assertTrue(any(why.startswith(prefix) and rid == report_id for why, rid in rows), (prefix, report_id, rows))

    def test_markdown_table_per_work_with_intervals(self):
        markdown = (self.out / "score.md").read_text(encoding="utf-8")
        self.assertIn("| sunni:muslim | 2/2 |", markdown)
        self.assertIn("4/5 = 80% (38-96)", markdown)


class ScoreUnitTests(unittest.TestCase):
    def test_wilson_matches_the_published_audit_intervals(self):
        # round 4 README: 0/70 = 0.0-5.2%, 4/20 = 20.0% (8.1-41.6)
        low, high = wilson(0, 70)
        self.assertEqual((round(100 * low, 1), round(100 * high, 1)), (0.0, 5.2))
        low, high = wilson(4, 20)
        self.assertEqual((round(100 * low, 1), round(100 * high, 1)), (8.1, 41.6))

    def test_comparison_forms(self):
        self.assertEqual(fold_exact("عِدَّةٌ  مِنْ‏ أَصْحَابِنَا،"), "عدة من أصحابنا")
        self.assertTrue(loosely_equal(("وحدثنيه أبو بكر بن نافع", "غندر"), ("أبو بكر بن نافع", "غندر")))   # a verb left in the stored surface
        self.assertFalse(loosely_equal(("أبو بكر", "غندر"), ("أبو بكر", "شعبة")))
        self.assertFalse(loosely_equal(("أ", "ب"), ("أ", "ب", "ج")))


if __name__ == "__main__":
    unittest.main()
